function validate(input) {
  const [{ Bikes = [] }] = input;
  const ids = new Set(), last = new Map();
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  for (const [id, bike, start, end] of Bikes) {
    if (id === null || bike === null || start === null || end === null) return 'ride_id, bike_number, start_time and end_time are required.';
    if (ids.has(id)) return `ride_id ${id} appears twice in Bikes.`;
    ids.add(id);
    if (!stamp.test(start) || !stamp.test(end)) return `Ride ${id} needs times as YYYY-MM-DD HH:MM:SS.`;
    if (start >= end) return `Ride ${id} must end after it starts.`;
    const key = String(bike).toLowerCase();
    if (!last.has(key) || last.get(key) < end) last.set(key, end);
  }
  if (new Set(last.values()).size < last.size) return 'Two bikes share the same latest end_time.';
  return null;
}

