function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const base = Date.UTC(2012, 2, 20);
  const fmt = minutes => new Date(base + minutes * 60000).toISOString().slice(0, 19).replace('T', ' ');
  const small = size === 'small';
  const bikeCount = small ? pick(5) : 300;
  const budget = small ? 8 : 2000;
  // Each bike first gets a distinct last end time; its other rides end strictly earlier,
  // sometimes after other bikes' last rides, so ordering by anything else goes wrong.
  const lastEnds = new Set();
  while (lastEnds.size < bikeCount) lastEnds.add(small ? 4320 + 10 * pick(100) : 4320 + pick(100000));
  const rides = [];
  [...lastEnds].forEach((end, i) => {
    const bike = 'W' + String(small ? [576, 300, 455, 120][i] : 100 + i).padStart(5, '0');
    const extra = small ? pick(3) : pick(12);
    let previousEnd = end;
    for (let r = 0; r <= extra && rides.length < budget; r++) {
      const finish = r === 0 ? end : previousEnd - (small ? 10 + 10 * pick(60) : 1 + pick(3000));
      const start = finish - (small ? 10 + 10 * pick(12) : 5 + pick(200));
      rides.push([bike, fmt(start), fmt(finish)]);
      previousEnd = finish;
    }
  });
  // Shuffle rows and number them, so ride_id carries no hint about recency.
  for (let i = rides.length - 1; i > 0; i--) { const j = pick(i + 1); [rides[i], rides[j]] = [rides[j], rides[i]]; }
  const Bikes = rides.map((ride, i) => [i + 1, ...ride]);
  return [{ Bikes }];
}
